function authDialog(mode='login',draft={}){const registration=mode==='register';modal.classList.add('auth-dialog');formAsync(registration?'Создайте своё хозяйство':'С возвращением!',`<div class="auth-brand"><img src="art/house.svg" alt=""><span>farm-off<small>Своё ближе, чем кажется</small></span></div><div class="auth-tabs" role="tablist" aria-label="Вход или регистрация"><button type="button" role="tab" aria-selected="${!registration}" onclick="switchAuthTab('login')">Войти</button><button type="button" role="tab" aria-selected="${registration}" onclick="switchAuthTab('register')">Регистрация</button></div><p class="auth-intro">${registration?'Своя грядка, забота садовника и урожай к вашему столу.':'Войдите, чтобы заглянуть на свои грядки.'}</p>${registration?`<label for="auth-name">Как вас зовут<input id="auth-name" name="name" required maxlength="60" autocomplete="name" placeholder="Ваше имя" value="${esc(draft.name||'')}"></label>`:''}<label for="auth-login">Логин<input id="auth-login" name="login" required minlength="3" maxlength="40" pattern="[A-Za-z0-9_-]{3,40}" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="Например, green_garden" value="${esc(draft.login||'')}"></label>${registration?'<p class="auth-hint">От 3 до 40 символов: латинские буквы, цифры, _ или -.</p>':''}<label for="auth-password">Пароль</label><div class="auth-password"><input id="auth-password" name="password" type="password" required minlength="12" maxlength="128" autocomplete="${registration?'new-password':'current-password'}" placeholder="${registration?'Придумайте надёжный пароль':'Введите пароль'}"><button type="button" aria-label="Показать пароль" aria-pressed="false" onclick="toggleAuthPassword(this)">Показать</button></div>${registration?'<p class="auth-hint">Не менее 12 символов. Сохраните пароль: восстановление доступа пока не подключено.</p>':''}<button class="btn auth-submit">${registration?'Зарегистрироваться':'Войти в хозяйство'}</button><p class="auth-switch">${registration?'Уже есть аккаунт?':'Пока нет аккаунта?'} <button type="button" onclick="switchAuthTab('${registration?'login':'register'}')">${registration?'Войти':'Зарегистрироваться'}</button></p>${!registration?'<details class="auth-help"><summary>Не получается войти?</summary><p>Проверьте логин, язык клавиатуры и пароль. Восстановление пароля пока не подключено.</p></details>':''}`,async f=>{const buttons=[...document.querySelectorAll('.auth-tabs button,.auth-switch button')];buttons.forEach(b=>b.disabled=true);try{await api(mode,{login:f.get('login'),password:f.get('password'),...(registration?{name:f.get('name')}:{})});await refreshCloud();location.hash='home';toast(registration?'Добро пожаловать в своё хозяйство!':'Вы вошли в своё хозяйство')}finally{buttons.forEach(b=>b.disabled=false)}});modal.setAttribute('aria-label',registration?'Регистрация':'Вход');}
function switchAuthTab(mode){if(document.querySelector('#form').getAttribute('aria-busy')==='true')return;const f=new FormData(document.querySelector('#form'));authDialog(mode,{name:f.get('name')||'',login:f.get('login')||''});document.querySelector(mode==='register'?'#auth-name':'#auth-login')?.focus()}
function toggleAuthPassword(button){const input=document.querySelector('#auth-password'),visible=input.type==='password';input.type=visible?'text':'password';button.textContent=visible?'Скрыть':'Показать';button.setAttribute('aria-label',visible?'Скрыть пароль':'Показать пароль');button.setAttribute('aria-pressed',String(visible))}
modal.addEventListener('close',()=>{modal.classList.remove('auth-dialog');modal.removeAttribute('aria-label');const password=document.querySelector('#auth-password');if(password)password.value=''});
